// Lit la réponse de Claude, vérifie les valeurs et prépare la ligne du tableau.
const CATEGORIES = ["Action requise", "Client / Mission", "Travail", "Facture / Paiement", "Administratif", "Notification", "Newsletter", "Promo", "Personnel"];
const PRIORITES = ['haute', 'moyenne', 'basse'];
const A_VERIFIER = 'À vérifier';

const mail = $('Préparer le mail').item.json;
const res = $json;

// 1. Extraire le JSON renvoyé par Claude (bloc de type "text", fin normale)
let data = null;
try {
  const bloc = (res.content || []).find(b => b.type === 'text');
  if (bloc && res.stop_reason === 'end_turn') {
    const texte = bloc.text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    data = JSON.parse(texte);
  }
} catch (e) {
  data = null;
}

// 2. Valider chaque champ, avec repli si la valeur est absente ou hors liste
const valide = data && typeof data === 'object';
const categorie = valide && CATEGORIES.includes(data.categorie) ? data.categorie : A_VERIFIER;
const priorite = valide && PRIORITES.includes(data.priorite) ? data.priorite : 'moyenne';
const resume = valide && typeof data.resume === 'string' && data.resume.trim()
  ? data.resume.trim().slice(0, 200)
  : mail.subject;
const action = valide && typeof data.action === 'string' ? data.action.trim().slice(0, 200) : '';

// 3. Mettre en forme les dates (fuseau Europe/Paris)
const recu = DateTime.fromISO(String(mail.date));
const dateTexte = recu.isValid
  ? recu.setZone('Europe/Paris').toFormat('yyyy-MM-dd HH:mm')
  : String(mail.date || '');

// 4. Une ligne par mail ; les clés = les en-têtes de colonnes du Google Sheet
return {
  json: {
    'Date': dateTexte,
    'Expéditeur': mail.from_name,
    'Email': mail.from_email,
    'Objet': mail.subject,
    'Catégorie': categorie,
    'Priorité': priorite,
    'Résumé': resume,
    'Action': action,
    'Lien': 'https://mail.google.com/mail/u/0/#all/' + mail.message_id,
    'Message ID': mail.message_id,
    'Traité le': DateTime.now().setZone('Europe/Paris').toFormat('yyyy-MM-dd HH:mm'),
  },
};

// L'appel à Claude a échoué après 3 essais : on écrit une ligne "Erreur API".
// Le mail sera retraité par le déclencheur "Reprise des erreurs" (toutes les 6 h à hh:37).
const mail = $('Préparer le mail').item.json;
const erreur = String(($json.error && ($json.error.message || $json.error)) || 'erreur inconnue').slice(0, 150);
const recu = DateTime.fromISO(String(mail.date));
return {
  json: {
    'Date': recu.isValid ? recu.setZone('Europe/Paris').toFormat('yyyy-MM-dd HH:mm') : String(mail.date || ''),
    'Expéditeur': mail.from_name,
    'Email': mail.from_email,
    'Objet': mail.subject,
    'Catégorie': 'Erreur API',
    'Priorité': 'moyenne',
    'Résumé': mail.subject,
    'Action': 'Reprise automatique prévue (' + erreur + ')',
    'Lien': 'https://mail.google.com/mail/u/0/#all/' + mail.message_id,
    'Message ID': mail.message_id,
    'Traité le': DateTime.now().setZone('Europe/Paris').toFormat('yyyy-MM-dd HH:mm'),
  },
};
